class DLinkedNode {
    int key;
    int val;
    DLinkedNode next;
    DLinkedNode prev;
    public DLinkedNode(){}
    public DLinkedNode(int key, int val){
        this.key = key;
        this.val = val;
    }
}
class LRUCache {
    DLinkedNode head;
    DLinkedNode tail;
    int capacity;
    int size;
    HashMap<Integer, DLinkedNode> cache;

    public LRUCache(int capacity) {
        head = new DLinkedNode();
        tail = new DLinkedNode();
        head.next = tail;
        tail.prev = head;
        this.capacity = capacity;
        size = 0;
        cache = new HashMap<>();
    }

    public int get(int key) {
        DLinkedNode node = cache.get(key);
        if(node == null){
            return -1;
        } else {
            moveToHead(node);
            return node.val;
        }
    }

    public void put(int key, int value) {
        DLinkedNode node = cache.get(key);
        if(node == null){
            DLinkedNode newnode = new DLinkedNode(key,value);
            addToHead(newnode);
            cache.put(key,newnode);
            size++;
            if(size > capacity){
                DLinkedNode deNode = removeTailNode();
                cache.remove(deNode.key);
                size--;
            }
        } else {
            node.val = value;
            moveToHead(node);
        }
    }
    // 用于新节点创建和被moveToHead()调用
    private void addToHead(DLinkedNode node){
        node.next = head.next;
        node.prev = head;
        head.next.prev = node;
        head.next = node;
    }
    private void removeNode(DLinkedNode node){
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }
    public void moveToHead(DLinkedNode node){
        removeNode(node);
        addToHead(node);
    }
    public DLinkedNode removeTailNode(){
        DLinkedNode res = tail.prev;
        removeNode(res);
        return res;
    }
}
